// Code 1 - Organizar investimentos
// Recebe o CSV como texto e transforma em uma tabela (1 item por investimento)
const csv = $input.first().json.data;
const [cabecalho, ...linhas] = csv.trim().split(/\r?\n/);
const colunas = cabecalho.split(',').map(c => c.trim());

return linhas
  .filter(l => l.trim())
  .map(linha => {
    const valores = linha.split(',').map(v => v.trim());
    const inv = Object.fromEntries(colunas.map((c, i) => [c, valores[i]]));
    const minimo = Number(inv.minimo);

    return {
      json: {
        perfil: inv.perfil,
        produto: inv.produto,
        minimo,
        minimo_formatado: minimo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
        rentabilidade: inv.rentabilidade
      }
    };
  });

// Code 2 - Mensagens personalizadas
// Do Merge vem cada cliente junto com os investimentos do seu perfil (match por "perfil").
// Para cada cliente escolhemos o investimento que cabe no saldo e criamos a mensagem.
const paraNumero = (txt) => Number(String(txt).replace(/[^\d,]/g, '').replace(',', '.')) || 0;

const templates = {
  Conservador: (c) => `Olá, ${c.nome}! Como seu perfil é Conservador, priorizamos segurança e renda fixa. Com seu saldo de ${c.saldo}, recomendamos ${c.produto} (rentabilidade ${c.rentabilidade}, aplicação mínima ${c.minimo_formatado}): baixo risco e previsibilidade para seu dinheiro.`,
  Moderado: (c) => `Olá, ${c.nome}! Seu perfil Moderado busca equilíbrio entre renda fixa e variável. Com seu saldo de ${c.saldo}, sugerimos ${c.produto} (rentabilidade ${c.rentabilidade}, aplicação mínima ${c.minimo_formatado}) para diversificar com risco controlado.`,
  Arrojado: (c) => `Olá, ${c.nome}! Como investidor Arrojado, você busca maior potencial de retorno. Com seu saldo de ${c.saldo}, indicamos ${c.produto} (rentabilidade ${c.rentabilidade}, aplicação mínima ${c.minimo_formatado}), com foco em renda variável e crescimento no longo prazo.`
};

// 1) Agrupar os matches por cliente (email)
const porCliente = {};
for (const item of $input.all()) {
  const linha = { ...item.json, saldo_numerico: paraNumero(item.json.saldo) };
  (porCliente[linha.email] ||= []).push(linha);
}

// 2) Maior aplicação mínima que cabe no saldo; se nenhuma couber, a menor
return Object.values(porCliente).map(opcoes => {
  const cabem = opcoes.filter(o => o.minimo <= o.saldo_numerico).sort((a, b) => b.minimo - a.minimo);
  const c = cabem[0] || opcoes.sort((a, b) => a.minimo - b.minimo)[0];

  return {
    json: {
      nome: c.nome,
      email: c.email,
      saldo: c.saldo,
      perfil: c.perfil,
      investimento: c.produto,
      rentabilidade: c.rentabilidade,
      minimo_formatado: c.minimo_formatado,
      saldo_suficiente: c.minimo <= c.saldo_numerico,
      outras_opcoes: opcoes.filter(o => o.produto !== c.produto).map(o => `${o.produto} (${o.rentabilidade}, mín. ${o.minimo_formatado})`).join('; '),
      mensagem_padrao: templates[c.perfil]
        ? templates[c.perfil](c)
        : `Olá, ${c.nome}! Ainda não temos uma recomendação para o perfil "${c.perfil}".`
    }
  };
});

