// Code 3 - Pós-processamento do e-mail
// Garante que cada item saia com emailTo, subject, textBody (e htmlBody) válidos,
// mesmo que a IA falhe ou devolva algo fora do formato.
const clientes = $('Code 2 - Mensagens personalizadas').all();   // mesma ordem do AI Agent
const emailValido = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(e || '').trim());

// Remove markdown, aspas e espaços sobrando
const limpar = (t) => String(t || '')
  .replace(/\*\*|__|##+|`/g, '')
  .replace(/^["'\s]+|["'\s]+$/g, '')
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const escaparHtml = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item, i) => {
  const c = clientes[i].json;

  // A saída do Agent pode vir como objeto (parser) ou como texto JSON
  let out = item.json.output;
  if (typeof out === 'string') {
    try { out = JSON.parse(out.replace(/^```(json)?|```$/g, '').trim()); }
    catch { out = { corpo: out }; }
  }
  out = out || {};

  const primeiroNome = String(c.nome).split(' ')[0];
  let subject = limpar(out.assunto).replace(/\n/g, ' ');
  let textBody = limpar(out.corpo);
  const usouFallback = { subject: !subject, textBody: textBody.length < 40 };

  if (usouFallback.subject) subject = `${primeiroNome}, uma recomendação de investimento para você`;
  if (subject.length > 90) subject = subject.slice(0, 87).trimEnd() + '...';
  if (usouFallback.textBody) textBody = `${c.mensagem_padrao}\n\nEquipe de Investimentos`;
  if (!/Equipe de Investimentos\s*$/.test(textBody)) textBody += '\n\nAtenciosamente,\nEquipe de Investimentos';

  const htmlBody = textBody
    .split(/\n\s*\n/)
    .map(p => `<p>${escaparHtml(p).replace(/\n/g, '<br>')}</p>`)
    .join('\n');

  return {
    json: {
      emailTo: String(c.email).trim().toLowerCase(),
      emailValido: emailValido(c.email),
      nome: c.nome,
      perfil: c.perfil,
      saldo: c.saldo,
      investimento: c.investimento,
      rentabilidade: c.rentabilidade,
      subject,
      textBody,
      htmlBody,
      geradoPorIA: !usouFallback.subject && !usouFallback.textBody
    }
  };
});
